content: |-
  <%_
  const currentRegionEsj = (() => {
    const currentRegion = String(getvar('stat_data.Bản tôn.Hành tung.Khu vực hiện tại', { defaults: '' }) || '').trim();
    const currentLayer = String(getvar('stat_data.Bản tôn.Hành tung.Tầng cấp trực thuộc', { defaults: '' }) || '').trim();
    const navigationInfo = String(getvar('stat_data.Bản tôn.Hành tung.Thông tin dẫn đường', { defaults: '' }) || '').trim();
    const identityFaction = String(getvar('stat_data.Bản tôn.Thân phận.Tông môn', { defaults: '' }) || '').trim();
    const currentSituation = String(getvar('stat_data.Hoàn cảnh hiện tại', { defaults: '' }) || '').trim();
    const derivedDomainName = String(getvar('__sect_prompt_state.domain', { defaults: '' }) || getvar('stat_data.$Suy đoán tông môn.Vực hiện tại', { defaults: '' }) || '').trim();
    const derivedFactionName = String(getvar('__sect_prompt_state.faction', { defaults: '' }) || getvar('stat_data.$Suy đoán tông môn.Thế lực chính hiện tại', { defaults: '' }) || '').trim();
    const directCtx = `${currentRegion} ${currentLayer}`;

    const domains = [
      {
        name: 'Thần Châu',
        aliases: ['Thần Châu', 'Trung Châu', 'Hoàng Thành', 'Vấn Đạo Phong', 'Kiếm Môn Quan', 'Long Môn Bộc Bố'],
        theme: 'Trật tự sâm nghiêm, nhân quả rõ ràng, vương quyền phàm tục cùng tiên đạo đứng song song tranh đấu.',
        factions: ['Đại Hạ Tiên Triều', 'Vong Cơ Kiếm Lư', 'Thái Hư Thận Lâu', 'Vạn Tượng Sâm La Phường', 'Thiên Cơ Quỷ Thị', 'Cửu U Luyện Hồn Tông'],
        style: 'Trọng quy củ, trọng lập trường, trọng thân phận lai lịch; ân oán thường dính líu đến pháp thống và khí vận.',
        risk: 'Dễ cuốn vào thiên cơ, vương pháp, nhân quả giao dịch, tình báo hắc thị cùng sự tranh giành chính thống.'
      },
      {
        name: 'Đông Thương',
        aliases: ['Đông Thương', 'Kiến Mộc', 'Thanh Đế Lăng', 'Bách Hoa Bí Cảnh', 'Long Miên Hải'],
        theme: 'Sinh cơ mênh mông mà túc mệnh thâm trầm, chú trọng nhất khô vinh, sinh tử cùng thiên mệnh luân chuyển.',
        factions: ['Thương Mộc Long Ngâm Các', 'Linh Xu Bách Thảo Cốc', 'Phù Vân Triêu Lộ Các', 'Kính Hoa Thủy Nguyệt Am'],
        style: 'Ngoài mềm trong dị, thường lấy khẩu khí bi mẫn làm việc cực đoan, dưới lớp vỏ ôn hòa ẩn chứa quan niệm đạo đức dị thường.',
        risk: 'Dễ cuốn vào địa mạch, linh thực, y độc, yêu tu, đỉnh lô thải bổ cùng những lựa chọn túc mệnh.'
      },
      {
        name: 'Nam Viêm',
        aliases: ['Nam Viêm', 'Bất Diệt Hỏa Sơn', 'Địa Hỏa Quật', 'Niết Bàn Đài', 'Ly Hỏa Cung'],
        theme: 'Hỏa tính rực cháy, sùng bái thiêu rụi, tôi luyện, đúc lại và hướng về cái chết để tái sinh.',
        factions: ['Chiêu Minh Phá Trận Tông', 'Đại Dã Thiên Công Lô', 'Kiếp Hôi Thần Từ', 'Uyên Hỏa Linh Tộc', 'Thực Nguyệt Huyết Hải Tông'],
        style: 'Ít mưu mô, nhiều cực đoan; phần thân chứng đạo, dung lô tế khí, hành sự thường quyết liệt hơn lời nói.',
        risk: 'Dễ cuốn vào tế hỏa, luyện khí, thử luyện huyết dũng, cướp đoạt huyết mạch cùng bùng nổ mất kiểm soát.'
      },
      {
        name: 'Tây Canh',
        aliases: ['Tây Canh', 'Vạn Kiếm Cổ Trủng', 'Canh Kim Khoáng Mạch', 'Bạch Hổ Thiên Tiệm', 'Triều Âm Hải'],
        theme: 'Kim sát hoành không, chuộng sát phạt, quân trận, khoáng mạch cùng bi mẫn thiết huyết.',
        factions: ['Tàng Phong Liễm Ngạc Sơn Trang', 'Chiết Kích Trầm Sa Cốc', 'Thái Bạch Sát Sinh Trủng', 'Vô Sinh Kiếm Phái', 'Thi Cốt Phù Đồ Tháp', 'Quỳnh Luân Thùy Diệu Cung', 'Thanh Vũ Vân Tước'],
        style: 'Xem trọng hiệu suất, xem trọng cái giá, xem trọng sự cứng cỏi; ngoài miệng ít lời thừa, dưới tay thấy chân chương.',
        risk: 'Dễ cuốn vào khoáng mạch, chiến trận, chiến trường xưa, tranh đoạt thi hài, ám lưu tình báo cùng lựa chọn lấy sát ngăn loạn.'
      },
      {
        name: 'Bắc Minh và U Giới',
        aliases: ['Bắc Minh', 'Huyền Băng Sơn', 'Minh Hải', 'Giao Nhân', 'Huyền Vũ', 'Quy Khư Hải Nhãn', 'Hoàng Tuyền', 'Vong Xuyên', 'Nại Hà Kiều', 'Minh Hà'],
        theme: 'Minh thủy trầm trọng, huyền băng ngập biển, tại nơi giao giới sinh tử, pháp độ luân hồi đan xen cùng tồn tại với sức mạnh tịch diệt.',
        factions: ['Tọa Vong Minh Hải Các', 'Khấp Châu Huyễn Hải Đình', 'Độ Ách U Phàm', 'Bỉ Ngạn Đề Đăng Nhân', 'Vô Gian Luân Hồi Đạo', 'Vong Xuyên Phong Nguyệt Lâu'],
        style: 'Một nửa bàn pháp độ, một nửa bán dục niệm; bề ngoài tĩnh lặng khắc chế, thực chất ai ai cũng nhìn chằm chằm hải trình biển sâu, pháp độ luân hồi cùng chốn về kiếp sau.',
        risk: 'Dễ cuốn vào dị động hải nhãn, huyễn cảnh giao ca, cái giá qua sông, luân hồi huyễn cảnh cùng chủ nợ kiếp trước tìm tới cửa.'
      }
    ];

    const factions = [
      { name: 'Đại Hạ Tiên Triều', domain: 'Thần Châu', aliases: ['Đại Hạ', 'Tiên Triều', 'Hoàng Thành', 'Triều Đình'] },
      { name: 'Vong Cơ Kiếm Lư', domain: 'Thần Châu', aliases: ['Kiếm Lư', 'Vấn Kiếm', 'Kiếm Môn', 'Cổ Kiếm'] },
      { name: 'Thái Hư Thận Lâu', domain: 'Thần Châu', aliases: ['Thận Lâu', 'Thiên Cơ', 'Suy Diễn', 'Mệnh Bàn'] },
      { name: 'Vạn Tượng Sâm La Phường', domain: 'Thần Châu', aliases: ['Sâm La Phường', 'Phường Thị', 'Hắc Thị', 'Giao Dịch'] },
      { name: 'Thiên Cơ Quỷ Thị', domain: 'Thần Châu', aliases: ['Thiên Cơ', 'Quỷ Thị', 'tình báo', 'ám sát'] },
      { name: 'Cửu U Luyện Hồn Tông', domain: 'Thần Châu', aliases: ['Cửu U', 'Luyện Hồn', 'Vạn Hồn Phiên', 'hồn phách'] },
      { name: 'Thương Mộc Long Ngâm Các', domain: 'Đông Thương', aliases: ['Long Ngâm Các', 'Kiến Mộc', 'Thanh Đế Lăng'] },
      { name: 'Linh Xu Bách Thảo Cốc', domain: 'Đông Thương', aliases: ['Bách Thảo Cốc', 'Dược Cốc', 'linh phố', 'đan phòng'] },
      { name: 'Phù Vân Triêu Lộ Các', domain: 'Đông Thương', aliases: ['Triều Lộ Các', 'phù đảo', 'ca yến', 'nhã tập'] },
      { name: 'Kính Hoa Thủy Nguyệt Am', domain: 'Đông Thương', aliases: ['Kính Hoa', 'Thủy Nguyệt Am', 'thải bổ', 'đỉnh lô'] },
      { name: 'Chiêu Minh Phá Trận Tông', domain: 'Nam Viêm', aliases: ['Chiêu Minh Phá Trận Tông', 'Chiêu Minh', 'Phá Trận Tông', 'Liệt Hỏa Thương Mang', 'Phá Trận Thương Trận'] },
      { name: 'Đại Dã Thiên Công Lô', domain: 'Nam Viêm', aliases: ['Thiên Công Lô', 'dung lô', 'khí phường', 'chú khí'] },
      { name: 'Kiếp Hôi Thần Từ', domain: 'Nam Viêm', aliases: ['thần từ', 'kiếp hôi', 'tế hỏa', 'phần thân'] },
      { name: 'Uyên Hỏa Linh Tộc', domain: 'Nam Viêm', aliases: ['Hỏa Linh', 'nham tương', 'Viêm Linh', 'dung nham'] },
      { name: 'Thực Nguyệt Huyết Hải Tông', domain: 'Nam Viêm', aliases: ['Huyết Hải Tông', 'Thực Nguyệt', 'hóa huyết', 'thôn phệ'] },
      { name: 'Tàng Phong Liễm Ngạc Sơn Trang', domain: 'Tây Canh', aliases: ['sơn trang', 'khoáng mạch', 'Canh Kim', 'Chú Phong'] },
      { name: 'Chiết Kích Trầm Sa Cốc', domain: 'Tây Canh', aliases: ['Trầm Sa Cốc', 'chiến trận', 'quân trận', 'binh qua'] },
      { name: 'Thái Bạch Sát Sinh Trủng', domain: 'Tây Canh', aliases: ['Sát Sinh Trủng', 'Vạn Kiếm Cổ Trủng', 'Bạch Hổ', 'sát phạt'] },
      { name: 'Vô Sinh Kiếm Phái', domain: 'Tây Canh', aliases: ['Vô Sinh', 'Kiếm Phái', 'Sát Lục', 'Phong Kiếm'] },
      { name: 'Thi Cốt Phù Đồ Tháp', domain: 'Tây Canh', aliases: ['Phù Đồ Tháp', 'Thi Cốt', 'Luyện Thi', 'Hoán Cốt'] },
      { name: 'Quỳnh Luân Thùy Diệu Cung', domain: 'Tây Canh', aliases: ['Quỳnh Luân', 'Thùy Diệu Cung', 'Nguyệt Quang', 'Nguyệt Hạ Hành Giả', 'Nữ Đế'] },
      { name: 'Thanh Vũ Vân Tước', domain: 'Tây Canh', aliases: ['Thanh Vũ Vân Tước', 'Thiên Uyên Chi Điểu', 'Thanh Vũ', 'Cực Tây Thiên Uyên', 'Uyên Khí'] },
      { name: 'Tọa Vong Minh Hải Các', domain: 'Bắc Minh và U Giới', aliases: ['Minh Hải Các', 'Tĩnh Hải', 'Băng Hải'] },
      { name: 'Khấp Châu Huyễn Hải Đình', domain: 'Bắc Minh và U Giới', aliases: ['Huyễn Hải Đình', 'Giao Nhân', 'Khấp Châu', 'Cựu Mộng'] },
      { name: 'Độ Ách U Phàm', domain: 'Bắc Minh và U Giới', aliases: ['U Phàm', 'Độ Khẩu', 'Bãi Độ'] },
      { name: 'Bỉ Ngạn Đề Đăng Nhân', domain: 'Bắc Minh và U Giới', aliases: ['Đề Đăng Nhân', 'Bỉ Ngạn', 'Dẫn Hồn', 'Hoàng Tuyền Lộ'] },
      { name: 'Vô Gian Luân Hồi Đạo', domain: 'Bắc Minh và U Giới', aliases: ['Vô Gian', 'Luân Hồi', 'Nghiệp Hỏa', 'Cứu Rỗi'] },
      { name: 'Vong Xuyên Phong Nguyệt Lâu', domain: 'Bắc Minh và U Giới', aliases: ['Phong Nguyệt Lâu', 'Vong Xuyên', 'Tiêu Kim Quật', 'Canh Mạnh Bà'] }
    ];

    const matchDomainByText = (text) => {
      if (!text) return null;
      return domains.find((item) => [item.name, ...item.aliases].some((alias) => text.indexOf(alias) !== -1)) || null;
    };
    const matchFactionByText = (text) => {
      if (!text) return null;
      return factions.find((item) => [item.name, ...item.aliases].some((alias) => text.indexOf(alias) !== -1)) || null;
    };

    const focusTexts = [
      identityFaction,
      currentSituation,
      navigationInfo,
      directCtx,
      derivedFactionName,
    ].filter(Boolean);
    const focus = focusTexts.map(matchFactionByText).find(Boolean) || null;
    const domain =
      (focus ? domains.find((item) => item.name === focus.domain) : null) ||
      matchDomainByText(currentSituation) ||
      matchDomainByText(navigationInfo) ||
      matchDomainByText(directCtx) ||
      domains.find((item) => item.name === derivedDomainName || item.aliases.includes(derivedDomainName));
    const orderedFactions =
      domain
        ? (focus && focus.domain === domain.name
            ? [focus.name, ...domain.factions.filter((name) => name !== focus.name)]
            : domain.factions)
        : [];

    return { domain, focus, orderedFactions };
  })();
  _%>
  【Tông Môn Địa Vực Hiện Tại】
  - Vị trí: <%= currentRegionEsj.domain ? currentRegionEsj.domain.name : 'Vùng đất chưa rõ' _%>
  - Đại thế: <%= currentRegionEsj.domain ? currentRegionEsj.domain.theme : 'Khí tượng tông môn nơi này chưa hiện rõ, nên trước hết phân định địa giới, thế lực hộ địa và thuộc tính địa mạch.' _%>
  - Tiêu điểm hiện tại: <%= currentRegionEsj.focus && currentRegionEsj.domain && currentRegionEsj.focus.domain === currentRegionEsj.domain.name ? `${currentRegionEsj.focus.name}, manh mối nơi này đã nghiêng rõ rệt về nhánh này.` : 'Tạm thời chưa có một tông môn duy nhất áp đảo toàn cục, hãy hiểu theo cục diện địa vực trước.' _%>
  - Thế lực hoạt động: <%= currentRegionEsj.orderedFactions.length ? currentRegionEsj.orderedFactions.join(', ') : 'Chưa rõ' _%>
  - Điểm chung hành sự: <%= currentRegionEsj.domain ? currentRegionEsj.domain.style : 'Trước tiên xem ai chiếm sơn môn, ai nắm linh mạch, ai giữ quyền lên tiếng tại bản địa.' _%>
  - Dễ sinh xung đột: <%= currentRegionEsj.domain ? currentRegionEsj.domain.risk : 'Phần lớn vẫn không thoát khỏi tranh đoạt cơ duyên, ân oán cũ, địa mạch cùng lợi ích.' _%>
